const depthFuture={ai:['코드·분석 초안의 자동화','여러 서비스·데이터의 신뢰성 통합','새 모델·사업·책임 구조에 재적응','비용·보안·정확도'],robots:['제한된 환경의 자동화','장비·서비스 사이 통합과 안전','새 기계·운영 방식으로 역량 이동','가격·고장·현장 적응'],health:['연구·기록·측정 지원','검증된 기술과 전문 판단 연결','새 임상·연구 도구와 교육 재학습','임상 검증·면허·안전'],energy:['예측·운영 최적화 지원','전력·건물·공정 통합','새 전원·자원·정책에 맞춘 설계 변경','투자·계통·정책'],security:['분류·탐지·시험 자동화','복합 위험·조직 대응 조정','새 공격·기술·책임 체계 재학습','공격 변화·허가·신뢰'],creative:['초안·일반 제작 자동화','사용자 경험·브랜드·상호작용 통합','새 매체·문화·권리 문제로 역할 확장','차별성·사용자·권리'],business:['자료·문서·집계 자동화','고객·제품·운영의 판단 조정','새 시장·사업·규칙에 재적응','수익성·경쟁·고객 수용'],education:['설명·자료·기록 지원','개인화 도구와 관계·지도 통합','평생학습·돌봄 방식의 변화에 적응','교육 효과·자격·관계'],city:['설계·경로·시설 운영 보조','시설·도시·물류 시스템 조정','새 인프라·이동·기후 조건에 적응','법규·안전·장기 투자'],food:['검사·생장·생산 기록 자동화','생물·공정·장비의 품질 통합','새 식품·자원·생산 방식에 적응','위생·환경·원가']};
const depthCareers=domains.flatMap(d=>depthRows[d.id].map((r,i)=>({id:d.id+'-'+i,domain:d.id,name:r[0],work:r[1],day:r[2],learn:r[3],trial:r[4],auto:r[5],human:r[6]})));
const depthChoices=new Set(),depthStrong=new Set(),depthLearn=new Set(),depthCompare=new Set();let depthExperience={},depthFeedback={};let depthMore=false,depthActive=null;
try{const s=JSON.parse(localStorage.getItem('compass-career-depth')||'{}');for(const x of s.refinements||[])if(depthRefinements.some(r=>r[0]===x))depthChoices.add(x);for(const [items,set,valid]of [[s.strong,depthStrong,subjectOptions],[s.learn,depthLearn,subjectOptions],[s.compare,depthCompare,depthCareers.map(c=>c.id)]])for(const x of items||[])if(valid.includes(x)&&(set!==depthCompare||set.size<2))set.add(x);for(const c of depthCareers){const e=s.experience?.[c.id];if(e&&typeof e==='object')depthExperience[c.id]={fun:['재미있음','보통','덜 재미있음'].includes(e.fun)?e.fun:'',retry:['다시 해보고 싶음','아직 모름','다른 것도 해보고 싶음'].includes(e.retry)?e.retry:'',hard:typeof e.hard==='string'?e.hard.slice(0,300):'',note:typeof e.note==='string'?e.note.slice(0,600):''}}if(s.feedback&&typeof s.feedback==='object')depthFeedback=s.feedback}catch{}
function depthSave(){try{localStorage.setItem('compass-career-depth',JSON.stringify({refinements:[...depthChoices],strong:[...depthStrong],learn:[...depthLearn],compare:[...depthCompare],experience:depthExperience,feedback:depthFeedback}));labSave()}catch{}}
function depthRank(weights={topic:3,activity:2,subject:1,refine:2}){return domains.map((d,i)=>{const exp=depthCareers.filter(c=>c.domain===d.id).map(c=>depthExperience[c.id]).filter(Boolean);const positive=exp.some(e=>e.fun==='재미있음'&&e.retry==='다시 해보고 싶음')?1:0;return {d,i,score:(labTopics.has(d.id)?weights.topic:0)+d.activities.filter(x=>chosenActivities.has(x)).length*weights.activity+d.subjects.filter(x=>chosenSubjects.has(x)).length*weights.subject+depthRefinements.filter(r=>depthChoices.has(r[0])&&r[2].includes(d.id)).length*weights.refine+positive}}).sort((a,b)=>b.score-a.score||a.i-b.i)}
labRank=()=>depthRank();
function depthSensitivity(){const options=[{topic:3,activity:2,subject:1,refine:2},{topic:2,activity:3,subject:1,refine:2},{topic:3,activity:1,subject:2,refine:2}];const lists=options.map(w=>depthRank(w).slice(0,3).map(x=>x.d.id));return {stable:lists.every(x=>x.join()===lists[0].join()),common:lists[0].filter(id=>lists.every(l=>l.includes(id))),lists}}
function depthReason(d){const r=labReason(d),fine=depthRefinements.filter(x=>depthChoices.has(x[0])&&x[2].includes(d.id)).map(x=>x[1]);const trial=depthCareers.some(c=>c.domain===d.id&&depthExperience[c.id]?.fun==='재미있음'&&depthExperience[c.id]?.retry==='다시 해보고 싶음');return r+(fine.length?'<br>세부 관심: '+fine.join(' · '):'')+(trial?'<br>체험 후 재미있고 다시 해보고 싶다고 기록했어요.':'')}
function depthControls(items,set,key){return `<div class="lab-picks">${items.map(x=>`<button data-depth-${key}="${labEsc(x)}" aria-pressed="${set.has(x)}" class="${set.has(x)?'selected':''}">${labEsc(x)}</button>`).join('')}</div>`}
function depthDetails(c){const d=domains.find(d=>d.id===c.domain),f=depthFuture[c.domain],e=depthExperience[c.id]||{};return `<article class="card depth-detail" id="career-role-detail"><h2>${c.name}</h2><p class="tag">업무 예시 · 회사·직무에 따라 달라요</p><h3>실제 하는 일</h3><p>${c.work}</p><h3>하루 업무 예시</h3><p>${c.day}</p><h3>학과·학교 과목·공부 순서</h3><p>${c.learn}</p><p>학교 기초 보완 → ${c.trial} → 결과와 오류를 설명하기. 대학의 필수 과목·실습·졸업 경로를 비교해요.</p><h3>이번 주 30분 체험</h3><p>5분: 질문 정하기 · 20분: ${c.trial} · 5분: 재미·어려움·재시도 기록. 제작·실험은 별도 시간과 안전한 지도가 필요할 수 있어요.</p><h3>AI가 바꿀 수 있는 업무</h3><p>자동화 후보: ${c.auto}<br>계속 연습할 판단: ${c.human}</p><details><summary>10·20·30년 뒤를 대비하는 시나리오</summary><p>확정 예측이 아닌 준비 질문입니다. 20·30년 구간은 특히 불확실해요.</p><p><strong>10년 관점</strong>: ${f[0]}가 진전된다면 ${c.human}을 실제 프로젝트로 연습.<br><strong>20년 관점</strong>: ${f[1]}가 중요해진다면 팀·시스템을 연결하는 경험 확장.<br><strong>30년 관점</strong>: ${f[2]}. 현재 직업명을 유지하는 것보다 이동 가능한 역량 점검.</p><p>확산 조건: ${f[3]}<br>이동 가능한 역량: ${c.human} · 설명·검증·협업<br>인접 분야 탐색: ${d.majors} 교육과정과 다른 역할 비교</p></details><div class="note">${d.risk}</div><h3>체험을 해본 뒤 기록하기</h3><label>재미 <select data-depth-experience="${c.id}" data-experience-key="fun"><option value="">아직 체험 전</option>${['재미있음','보통','덜 재미있음'].map(v=>`<option ${e.fun===v?'selected':''}>${v}</option>`).join('')}</select></label><label>다시 해볼 마음 <select data-depth-experience="${c.id}" data-experience-key="retry"><option value="">아직 체험 전</option>${['다시 해보고 싶음','아직 모름','다른 것도 해보고 싶음'].map(v=>`<option ${e.retry===v?'selected':''}>${v}</option>`).join('')}</select></label><label>어려웠던 부분 <textarea data-depth-experience="${c.id}" data-experience-key="hard" maxlength="300" rows="2">${labEsc(e.hard||'')}</textarea></label><label>배운 점·다음 질문 <textarea data-depth-experience="${c.id}" data-experience-key="note" maxlength="600" rows="3">${labEsc(e.note||'')}</textarea></label><p class="mini" role="status">기록은 입력할 때 이 브라우저에 저장돼요. 재미와 재시도 의지가 모두 긍정이면 해당 분야 탐색에 1점을 더해요. 어려움·부정적 응답으로 후보를 제외하지 않습니다.</p><button class="jobbutton" data-depth-rerank>체험 기록으로 다시 탐색</button> <button class="jobbutton" data-depth-compare="${c.id}" aria-pressed="${depthCompare.has(c.id)}">${depthCompare.has(c.id)?'비교에서 빼기':'이 직업 비교에 담기'}</button></article>`}
function depthCompareView(){return `<section class="section" id="depth-compare"><h2>직업 두 개 비교 · ${depthCompare.size}/2</h2><p id="depth-status" role="status">직업의 업무·학습·체험을 비교해요. 최대 두 개까지 담을 수 있어요.</p><div class="grid">${[...depthCompare].map(id=>{const c=depthCareers.find(c=>c.id===id);return `<article class="card"><h3>${c.name}</h3><p><strong>하는 일</strong><br>${c.work}</p><p><strong>하루 예시</strong><br>${c.day}</p><p><strong>학과·공부</strong><br>${c.learn}</p><p><strong>체험</strong><br>${c.trial}</p><p><strong>자동화될 수 있는 일</strong><br>${c.auto}</p><p><strong>사람의 판단</strong><br>${c.human}</p><button class="jobbutton" data-depth-role="${id}">자세히·체험 기록</button><button class="jobbutton" data-depth-compare="${id}">비교에서 빼기</button></article>`}).join('')}</div>${depthCompare.size?'':'<p>분야 카드의 직업 이름을 누르고 비교에 담아봐.</p>'}</section>`}
function depthStudentReview(){return `<details><summary>실제 학생 사용 점검 · 평가 과제와 기록</summary><p>아직 실제 학생 10명의 평가 결과가 없습니다. 고1 6명·고2 3명·고3 1명을 대상으로 아래 과제를 관찰하는 평가안입니다. 승준이도 스스로 점검할 수 있어요. 기록은 이 브라우저에만 저장되며 자동 제출되지 않아요.</p><ol><li>관심 3개를 골라 결과를 보기</li><li>추천된 이유를 자기 말로 설명하기</li><li>직업 두 개를 비교하기</li><li>30분 체험 계획 정하기</li><li>선택을 바꾸고 결과 차이 확인하기</li><li>기록 삭제 기능을 찾아보기</li></ol>${['선택이 쉬웠나요?','추천 이유를 이해했나요?','직업 비교를 쉽게 할 수 있나요?'].map((q,i)=>`<label>${q}<select data-depth-feedback="q${i}"><option value="">선택 안 함</option>${['1 어려움','2 조금 어려움','3 보통','4 쉬움','5 매우 쉬움'].map(v=>`<option ${depthFeedback['q'+i]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label>막힌 곳·이해 안 되는 말<textarea rows="3" maxlength="600" data-depth-feedback="comment">${labEsc(typeof depthFeedback.comment==='string'?depthFeedback.comment:'')}</textarea></label><p class="mini">실제 관찰 때는 도움 없이 완료했는지·걸린 시간·막힌 위치를 기록하세요. 점수는 적성 검사가 아니며 모집·실사용 전에는 만족도나 성공률을 보고하지 않습니다.</p></details>`}
const depthOriginalExplore=exploring;
exploring=function(){if(route==='flow')return depthOriginalExplore()+depthStudentReview();if(labStep===0){let s=depthOriginalExplore();const refine=`<section class="section"><h3>좋아하는 것의 어떤 부분이 재미있어?</h3><p>휴대폰도 디자인·비교·원리·설명·수리·앱 만들기로 나눠볼 수 있어. 다른 관심도 함께 골라봐.</p>${depthControls(depthRefinements.map(r=>r[0]),depthChoices,'refine').replace(/>([^<>]+)<\/button>/g,(m,id)=>'>'+labEsc(depthRefinements.find(r=>r[0]===id)?.[1]||id)+'</button>')}</section>`;return s.replace('<div class="lab-controls">',refine+'<div class="lab-controls">')+depthStudentReview()}
if(labStep===1){const s=depthOriginalExplore(),a=s.indexOf('<h2>좋아하는 과목'),b=s.indexOf('<div class="lab-controls">',a);const body=`<h2>좋아함·잘함·배우고 싶음을 나눠보자</h2><p>서로 달라도 괜찮아. 성적은 입력하지 않아도 돼.</p><h3>좋아하는 과목</h3>${labPick(subjectOptions,chosenSubjects,'subject')}<h3>지금 자신 있는 과목</h3>${depthControls(subjectOptions,depthStrong,'strong')}<h3>더 배우고 싶은 과목</h3>${depthControls(subjectOptions,depthLearn,'learn')}<p class="mini">좋아하는 과목만 탐색 순위에 반영해요. 자신 있는 과목은 시작점, 배우고 싶은 과목은 학습 목표로 안내하며 직업을 제외하지 않아요.</p><h3>해보고 싶은 활동</h3>${labPick(activityOptions,chosenActivities,'activity')}`;return s.slice(0,a)+body+s.slice(b)+depthStudentReview()}
if(labStep===2)return depthOriginalExplore()+depthStudentReview();const rows=depthRank(),visible=depthMore?rows:rows.slice(0,3),sens=depthSensitivity(),has=labTopics.size+chosenSubjects.size+chosenActivities.size+depthChoices.size;
return `<div class="tabs"><button data-route="flow">미래 변화에서 찾기</button><button data-route="self" class="active">나에게서 찾기</button></div><nav class="lab-steps" aria-label="진로 탐색 단계">${['관심 주제','과목·활동','일하는 방식','비교·체험'].map((x,i)=>`<button data-lab-step="${i}" ${i===3?'aria-current="step"':''}>${i+1}. ${x}</button>`).join('')}</nav><section class="lab-surface"><h2>${has?'먼저 살펴볼 분야 3개':'아직 모르겠다면 세 분야부터 구경하자'}</h2><p>추천은 탐색 순서야. 적성·합격·취업 확률은 아니며, 모든 분야를 더 볼 수 있어.</p><div class="note"><strong>추천 순서 안정성 확인</strong><br>${has?(sens.stable?'3가지 가중치 조합에서 첫 3개 분야의 순서가 같아요. 적성 검사의 신뢰도를 뜻하지는 않아요.':'과목·활동의 비중을 바꾸면 후보나 순서가 달라져요. 후보 하나보다 여러 분야의 체험을 비교해 봐.'):'선택이 없어서 기본 순서예요. 개인화 추천이 아닙니다.'}</div><details><summary>추천 규칙·민감도 분석이란?</summary><p>직접 주제 3점 + 일치 활동 각각 2점 + 좋아하는 과목 각각 1점 + 세부 관심과 연결되는 분야 각각 2점 + 긍정 체험 분야 1점. 동점은 기본 순서입니다. 자체 설계 가중치이며 심리검사 점수가 아닙니다.</p><p>민감도 분석(Sensitivity analysis)은 주제·활동·과목 비중을 3·2·1, 2·3·1, 3·1·2로 바꿔 결과를 비교하는 방법이에요. 세부 관심 2점과 체험 1점은 고정합니다. 자신 있는 과목·배울 과목·일하는 방식·부정 체험은 순위에 반영하지 않습니다.</p></details><div class="grid">${visible.map(({d},i)=>`<article class="card"><span class="tag">${has?'탐색 후보 '+(i+1):'자유 탐색'}</span><h3>${d.name}</h3><p>${depthReason(d).replace('具体','세부')}</p><p>${d.flow}</p><h3>어떤 역할이 궁금해?</h3><div class="depth-roles">${depthCareers.filter(c=>c.domain===d.id).map(c=>`<button data-depth-role="${c.id}">${c.name}</button>`).join('')}</div></article>`).join('')}</div><button class="jobbutton" data-depth-more>${depthMore?'처음 3개만 보기':'나머지 7개 분야 더 보기'}</button>${depthActive?depthDetails(depthCareers.find(c=>c.id===depthActive)):''}${depthCompareView()}<section class="card section"><h2>이번 주 30분 실천</h2><p>궁금한 직업 하나를 열고 구체적인 체험 과제를 골라봐. 실제로 해본 뒤 재미·어려움·재시도 마음을 기록하고 추천을 다시 확인해.</p><p><strong>학습 시작점</strong>: ${[...depthStrong].map(labEsc).join(' · ')||'자신 있는 과목은 아직 선택하지 않았어요.'}<br><strong>배울 목표</strong>: ${[...depthLearn].map(labEsc).join(' · ')||'체험에서 궁금해진 과목을 골라도 돼요.'}</p><button class="jobbutton" data-page="plan">12주 준비계획 연결</button><p>전문대·직업교육·4년제의 교육과정·실습·비용을 비교해요. 전형·선택과목·면허는 해당 기관의 최신 공식 안내를 확인하세요.</p><a href="https://www.career.go.kr/cloud/" target="_blank" rel="noopener">공식 직업·학과 정보와 별도 검사 보기</a></section><div class="lab-controls"><button data-lab-step="2">이전</button><button data-lab-step="0">관심 다시 고르기</button></div></section><p class="mini">선택·체험 기록은 이 브라우저에만 저장돼요.</p><button class="text-button" data-lab-reset>내 탐색 기록 지우기</button>${labReview()}${depthStudentReview()}`};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let changed=false;for(const [key,set,valid]of [['refine',depthChoices,depthRefinements.map(r=>r[0])],['strong',depthStrong,subjectOptions],['learn',depthLearn,subjectOptions]]){const v=b.dataset['depth'+key[0].toUpperCase()+key.slice(1)];if(v&&valid.includes(v)){set.has(v)?set.delete(v):set.add(v);changed=true}}
if(b.hasAttribute('data-depth-more')){depthMore=!depthMore;changed=true}if(b.dataset.depthRole&&depthCareers.some(c=>c.id===b.dataset.depthRole)){depthActive=b.dataset.depthRole;changed=true}if(b.dataset.depthCompare){const id=b.dataset.depthCompare;if(depthCareers.some(c=>c.id===id)){if(depthCompare.has(id))depthCompare.delete(id);else if(depthCompare.size<2)depthCompare.add(id);else{const el=document.querySelector('#depth-status');if(el)el.textContent='한 직업을 비교에서 빼면 다른 직업을 담을 수 있어요.';return}changed=true}}
if(b.hasAttribute('data-depth-rerank')){depthMore=false;changed=true}if(b.hasAttribute('data-lab-reset')){depthChoices.clear();depthStrong.clear();depthLearn.clear();depthCompare.clear();depthExperience={};depthFeedback={};depthActive=null;depthMore=false;changed=true}if(changed){depthSave();render();if(b.dataset.depthRole)document.querySelector('#career-role-detail')?.scrollIntoView({block:'start',behavior:'smooth'})}});
function depthInput(e){const t=e.target,id=t.dataset?.depthExperience,key=t.dataset?.experienceKey;if(id&&depthCareers.some(c=>c.id===id)&&['fun','retry','hard','note'].includes(key)){const limits={hard:300,note:600};const valid={fun:['','재미있음','보통','덜 재미있음'],retry:['','다시 해보고 싶음','아직 모름','다른 것도 해보고 싶음']};if(valid[key]&&!valid[key].includes(t.value))return;depthExperience[id]??={};depthExperience[id][key]=t.value.slice(0,limits[key]||40);depthSave()}const fk=t.dataset?.depthFeedback;if(['q0','q1','q2','comment'].includes(fk)){depthFeedback[fk]=t.value.slice(0,fk==='comment'?600:40);depthSave()}}
document.addEventListener('input',depthInput);document.addEventListener('change',depthInput);
if(location.hash==='#career-lab'){page='explore';route='self';render()}

// Keep keyboard focus on a multi-select control after its selected state renders.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;for(const k of ['depthRefine','depthStrong','depthLearn','labTopic','labSubject','labActivity','labWork']){if(b.dataset[k]){const attr=k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());document.querySelector('button[data-'+attr+'="'+b.dataset[k]+'"]')?.focus?.({preventScroll:true});break}}});
